1	import { supabase } from '$lib/supabaseClient';
2	import type { ReceiptInsert, ReceiptRow } from '$lib/models/Receipt';
3	import { withRetry } from '$lib/utils/retry';
4	import type { ReceiptExtract } from '$lib/utils/sanitize';
5	import { isSuspiciousDate } from '$lib/utils/dateValidation';
6	import { resolveOcrReceiptDate } from '$lib/utils/receiptDateCorrection';
7	import { resizeImage } from '$lib/utils/imageResize';
8	import { getSignedReceiptUrl } from '$lib/utils/signedUrl';
9	import { sanitizeFilename } from '$lib/utils/sanitizeFilename';
10	
11	const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];
12	const PDF_TYPE = 'application/pdf';
13	const MAX_IMAGE_MB = 5;
14	const MAX_PDF_MB = 10;
15	
16	/** The database row also carries family_id (set by trigger/RLS), which the model omits. */
17	type InsertedReceiptRow = ReceiptRow & { family_id: string | null };
18	
19	export class ReceiptService {
20		static #instance: ReceiptService | null = null;
21		static get(): ReceiptService {
22			return (this.#instance ??= new ReceiptService());
23		}
24	
25		/**
26		 * Call the server-side OCR API to extract receipt data
27		 */
28		private async extractOcrData(fileUrl: string, mimeType: string): Promise<ReceiptExtract | null> {
29			try {
30				const response = await fetch('/api/ocr/extract', {
31					method: 'POST',
32					headers: {
33						'Content-Type': 'application/json'
34					},
35					body: JSON.stringify({ fileUrl, mimeType })
36				});
37	
38				if (!response.ok) {
39					const errorText = await response.text();
40					throw new Error(`OCR API error: ${response.status} - ${errorText}`);
41				}
42	
43				const result = await response.json();
44				return result.data;
45			} catch (e) {
46				console.error('OCR extraction failed:', e);
47				return null;
48			}
49		}
50	
51		async list(
52			sort: 'transaction_date' | 'merchant_name' | 'total_amount' = 'transaction_date',
53			direction: 'asc' | 'desc' = 'desc'
54		) {
55			return withRetry(async () => {
56				const user = (await supabase.auth.getUser()).data.user;
57				if (!user) throw new Error('Not authenticated');
58	
59				console.log('[ReceiptService] Fetching receipts for user:', user.id);
60	
61				// Check family memberships for debugging
62				const { data: familyMemberships, error: fmError } = await supabase
63					.from('family_members')
64					.select('*')
65					.eq('user_id', user.id);
66				console.log('[ReceiptService] Family memberships:', familyMemberships, fmError);
67	
68				// Don't filter by user_id - let RLS policies handle access based on family membership
69				// This allows family members to see each other's receipts
70				const { data, error } = await supabase
71					.from('receipts')
72					.select('*')
73					.order(sort, { ascending: direction === 'asc' });
74				if (error) throw error;
75	
76				console.log('[ReceiptService] Fetched receipts:', {
77					count: data.length,
78					sample: data[0]
79						? {
80								id: data[0].id,
81								merchant_name: data[0].merchant_name,
82								family_id: data[0].family_id,
83								user_id: data[0].user_id
84							}
85						: 'none'
86				});
87	
88				return data as ReceiptRow[];
89			});
90		}
91	
92		/** Fields that are safe to send in an update — matches ReceiptInsert keys */
93		static readonly #EDITABLE_FIELDS: ReadonlySet<string> = new Set([
94			'receipt_image_path',
95			'transaction_date',
96			'total_amount',
97			'tax',
98			'merchant_name',
99			'credit_card_name',
100			'credit_card_last_4',
101			'currency',
102			'exchange_rate_to_cad',
103			'matched_transaction_id',
104			'suspicious_date',
105			'split_group_id'
106		]);
107	
108		async update(id: string, patch: ReceiptInsert) {
109			return withRetry(async () => {
110				// Strip non-editable fields (id, user_id, created_at, etc.) to prevent
111				// Supabase 400 errors from invalid values being sent in the update.
112				const safePatch: ReceiptInsert = {};
113				const source = patch as Record<string, unknown>;
114				const target = safePatch as Record<string, unknown>;
115				for (const key of Object.keys(patch)) {
116					if (ReceiptService.#EDITABLE_FIELDS.has(key)) {
117						target[key] = source[key];
118					}
119				}
120	
121				// #{#dtv1b} #{#dtv2d} Saving a receipt through the edit modal clears the
122				// suspicious-date flag. The modal always sends transaction_date, so a save
123				// (date corrected or left as-is) is treated as the user's review/confirmation
124				// of the date — there is no separate "confirm date" action. Only OCR/automated
125				// extraction sets the flag in the first place.
126				if ('transaction_date' in safePatch) {
127					safePatch.suspicious_date = false;
128				}
129	
130				const { data, error } = await supabase
131					.from('receipts')
132					.update(safePatch)
133					.eq('id', id)
134					.select('*')
135					.single();
136				if (error) throw error;
137				return data as ReceiptRow;
138			});
139		}
140	
141		async createManual(
142			values: Required<Pick<ReceiptInsert, 'merchant_name' | 'total_amount' | 'transaction_date'>> &
143				Partial<ReceiptInsert>
144		) {
145			return withRetry(async () => {
146				// Manual receipts are intentional - user is explicitly entering the date
147				// Skip suspicious date validation to avoid false positives for old receipts
148				const valuesWithFlag: ReceiptInsert = {
149					...values,
150					suspicious_date: false
151				};
152	
153				const { data, error } = await supabase
154					.from('receipts')
155					.insert(valuesWithFlag)
156					.select('*')
157					.single();
158				if (error) throw error;
159				return data as ReceiptRow;
160			});
161		}
162	
163		validateFile(file: File): { ok: true } | { ok: false; message: string } {
164			const type = file.type;
165			const sizeMB = file.size / (1024 * 1024);
166			if ([...IMAGE_TYPES, PDF_TYPE].indexOf(type) === -1) {
167				return { ok: false, message: 'Unsupported file type. Allowed: JPEG, PNG, HEIC, PDF.' };
168			}
169			if (IMAGE_TYPES.includes(type) && sizeMB > MAX_IMAGE_MB) {
170				return { ok: false, message: `Image too large. Max ${MAX_IMAGE_MB}MB.` };
171			}
172			if (type === PDF_TYPE && sizeMB > MAX_PDF_MB) {
173				return { ok: false, message: `PDF too large. Max ${MAX_PDF_MB}MB.` };
174			}
175			return { ok: true };
176		}
177	
178		/**
179		 * Upload a receipt file, extract its data via OCR, and persist the receipt row.
180		 *
181		 * Resilience invariants (see upload-pipeline-resilience spec):
182		 * - OCR is best-effort: any OCR failure still creates the receipt without extracted data.
183		 * - No orphan storage files: if the insert fails after upload, the blob is removed.
184		 */
185		async uploadAndCreate(file: File) {
186			const val = this.validateFile(file);
187			if (!val.ok) throw new Error(val.message);
188	
189			return withRetry(async () => {
190				const fileToUpload = await this.prepareFileForUpload(file);
191				const path = await this.uploadToStorage(fileToUpload);
192				const extract = await this.extractReceiptDataFailSoft(path, file.type);
193				const values = await this.buildReceiptInsert(file, path, extract);
194				const data = await this.insertReceiptOrCleanupUpload(values, path);
195				await this.autoAssignCategoryBestEffort(data, extract?.merchant_name ?? null);
196				return data as ReceiptRow;
197			});
198		}
199	
200		/** #{#rsz2a} Resize JPEG/PNG images before upload; falls back to the original on failure. */
201		private async prepareFileForUpload(file: File): Promise<File> {
202			const shouldResize = ['image/jpeg', 'image/png'].includes(file.type);
203			if (!shouldResize) return file;
204	
205			try {
206				const originalSize = file.size;
207				const resized = await resizeImage(file, 2000, 0.85);
208				const resizedSize = resized.size;
209	
210				console.log(
211					`Image resized: ${(originalSize / 1024).toFixed(2)}KB → ${(resizedSize / 1024).toFixed(2)}KB (${((1 - resizedSize / originalSize) * 100).toFixed(1)}% reduction)`
212				);
213				return resized;
214			} catch (error) {
215				console.error('Image resize failed, using original:', error);
216				return file; // Fall back to original
217			}
218		}
219	
220		/** Upload the file under the user's folder and return its storage path. Throws on failure. */
221		private async uploadToStorage(fileToUpload: File): Promise<string> {
222			const user = (await supabase.auth.getUser()).data.user;
223			if (!user) throw new Error('Not authenticated');
224			const folder = `${user.id}`;
225			const fileExt = fileToUpload.name.split('.').pop()?.toLowerCase() ?? 'bin';
226			const path = `${folder}/${crypto.randomUUID()}.${fileExt}`;
227			const { error: upErr } = await supabase.storage.from('receipts').upload(path, fileToUpload, {
228				contentType: fileToUpload.type,
229				upsert: false
230			});
231			if (upErr) throw upErr;
232			return path;
233		}
234	
235		/**
236		 * #{#sec2a} OCR via a short-lived signed URL. Best-effort: returns null when the signed
237		 * URL cannot be generated or the OCR API fails, so the upload pipeline survives outages.
238		 */
239		private async extractReceiptDataFailSoft(
240			path: string,
241			mimeType: string
242		): Promise<ReceiptExtract | null> {
243			const signedUrl = await getSignedReceiptUrl(path, 300);
244			return signedUrl ? await this.extractOcrData(signedUrl, mimeType) : null;
245		}
246	
247		/** #{#fcr1a} #{#fcr2a} Fetch exchange rate at scan time for foreign currency receipts. */
248		private async fetchExchangeRateBestEffort(
249			currency: string | null,
250			transactionDate: string | null
251		): Promise<number | null> {
252			if (!currency || currency === 'CAD' || !transactionDate) return null;
253			try {
254				const { ExchangeRateService } = await import('./ExchangeRateService');
255				return await ExchangeRateService.fetchRate(currency, transactionDate);
256			} catch {
257				// Rate fetch is best-effort — receipt is saved without rate
258				return null;
259			}
260		}
261	
262		/** Map the (possibly null) OCR extract onto the row to insert. */
263		private async buildReceiptInsert(
264			file: File,
265			path: string,
266			extract: ReceiptExtract | null
267		): Promise<ReceiptInsert> {
268			// #{#rdc4b} #{#rdc5a} Correct OCR date from the verbatim raw string, then derive
269			// the suspicious_date flag (#{#dtv1b}) from the corrected value. Implausible,
270			// uncorrectable dates (wrong-token reads) are flagged rather than silently stored.
271			const { transaction_date: transactionDate, suspicious_date } = resolveOcrReceiptDate(
272				extract?.transaction_date ?? null,
273				extract?.raw_date_text,
274				new Date()
275			);
276			const currency = extract?.currency ?? null;
277			const exchangeRate = await this.fetchExchangeRateBestEffort(currency, transactionDate);
278	
279			return {
280				receipt_image_path: path,
281				original_filename: sanitizeFilename(file.name), // #{#ofn2a} capture original name (pre-resize)
282				transaction_date: transactionDate,
283				total_amount: extract?.total_amount ?? null,
284				tax: extract?.tax ?? null,
285				merchant_name: extract?.merchant_name ?? null,
286				currency: currency,
287				exchange_rate_to_cad: exchangeRate,
288				credit_card_name: extract?.credit_card_name ?? null,
289				credit_card_last_4: extract?.credit_card_last_4 ?? null,
290				suspicious_date
291			};
292		}
293	
294		/**
295		 * #{#upr1a} #{#upr1b} Insert the receipt row. If the insert fails, the storage upload has
296		 * already created a blob that no row will ever reference — remove it before re-throwing so
297		 * it doesn't become an orphan. Cleanup failure is logged but doesn't mask the original
298		 * insert error — the caller sees what went wrong with the insert.
299		 */
300		private async insertReceiptOrCleanupUpload(
301			values: ReceiptInsert,
302			path: string
303		): Promise<InsertedReceiptRow> {
304			const { data, error } = await supabase.from('receipts').insert(values).select('*').single();
305			if (error) {
306				await this.removeUploadedFileBestEffort(path, error);
307				throw error;
308			}
309	
310			const row = data as InsertedReceiptRow;
311			console.log('[ReceiptService] Receipt created:', {
312				id: row.id,
313				merchant_name: row.merchant_name,
314				family_id: row.family_id,
315				user_id: row.user_id,
316				transaction_date: row.transaction_date
317			});
318			return row;
319		}
320	
321		/** Remove the just-uploaded blob; log (never throw) so the insert error stays visible. */
322		private async removeUploadedFileBestEffort(path: string, insertError: unknown): Promise<void> {
323			try {
324				const { error: removeErr } = await supabase.storage.from('receipts').remove([path]);
325				if (removeErr) {
326					console.error('orphan_storage_cleanup_failed', {
327						path,
328						insertError,
329						cleanupError: removeErr
330					});
331				}
332			} catch (cleanupError) {
333				console.error('orphan_storage_cleanup_failed', {
334					path,
335					insertError,
336					cleanupError
337				});
338			}
339		}
340	
341		/**
342		 * #{#vca2a} Auto-assign a category based on vendor rules. Graceful error handling:
343		 * failures are logged but never fail receipt creation.
344		 */
345		private async autoAssignCategoryBestEffort(
346			receipt: InsertedReceiptRow | null,
347			merchantName: string | null
348		): Promise<void> {
349			if (!merchantName || !receipt || !receipt.family_id) return;
350	
351			try {
352				// Dynamic import to avoid circular dependency
353				const { ExpenseService } = await import('./ExpenseService');
354				const expenseService = new ExpenseService(supabase);
355	
356				// Check for matching vendor rule using family_id
357				const vendorRule = await expenseService.getVendorRule(receipt.family_id, merchantName);
358				if (!vendorRule) return;
359	
360				// Auto-assign category with source='auto'
361				await expenseService.assignCategory(receipt.id, vendorRule.category_id, 'auto');
362	
363				// #{#vca3b} - Log auto-assignment for debugging
364				console.log(
365					JSON.stringify({
366						event: 'vendor_rule_auto_assign',
367						timestamp: new Date().toISOString(),
368						family_id: receipt.family_id,
369						receipt_id: receipt.id,
370						merchant_name: merchantName,
371						category_id: vendorRule.category_id,
372						category_name: vendorRule.category_name,
373						source: 'auto',
374						context: 'upload'
375					})
376				);
377			} catch (autoAssignError) {
378				// #{#vca2a} - Graceful error handling: log but don't fail receipt creation
379				console.error('Auto-assignment failed, receipt created without category:', autoAssignError);
380			}
381		}
382	
383		async delete(id: string, receiptImagePath?: string | null) {
384			return withRetry(async () => {
385				// determine storage path
386				let path = receiptImagePath ?? null;
387				if (!path) {
388					const { data, error } = await supabase
389						.from('receipts')
390						.select('receipt_image_path')
391						.eq('id', id)
392						.single();
393					if (error) throw error;
394					path = (data as { receipt_image_path: string | null } | null)?.receipt_image_path ?? null;
395				}
396	
397				// best-effort delete of storage object first to avoid orphan files
398				if (path) {
399					try {
400						await supabase.storage.from('receipts').remove([path]);
401					} catch {
402						// ignore storage deletion errors; proceed to delete DB row
403					}
404				}
405	
406				const { error: delErr } = await supabase.from('receipts').delete().eq('id', id);
407				if (delErr) throw delErr;
408				return { id };
409			});
410		}
411	
412		/**
413		 * #{#spl1a} Split a receipt into two partial receipts.
414		 *
415		 * Creates a new receipt with the specified split amount and reduces the
416		 * original receipt's amount accordingly. Both receipts share a split_group_id.
417		 *
418		 * @param receiptId The ID of the receipt to split
419		 * @param splitAmount The amount for the new split receipt
420		 * @returns The new receipt and the updated original
421		 */
422		async splitReceipt(
423			receiptId: string,
424			splitAmount: number,
425			splitDate?: string | null
426		): Promise<{ newReceipt: ReceiptRow; updatedOriginal: ReceiptRow }> {
427			// Validate inputs before any DB calls
428			ReceiptService.validateSplitAmount(splitAmount);
429			ReceiptService.validateSplitDate(splitDate);
430	
431			return withRetry(async () => {
432				// Auth check
433				const user = (await supabase.auth.getUser()).data.user;
434				if (!user) throw new Error('Not authenticated');
435	
436				const original = await this.fetchOriginalForSplit(receiptId);
437				const remainingAmount = ReceiptService.computeRemainingAmount(
438					original.total_amount,
439					splitAmount
440				);
441	
442				// #{#spl1b} - Determine split_group_id
443				const splitGroupId = original.split_group_id ?? crypto.randomUUID();
444	
445				// #{#spl5a} - Insert new receipt first, then update original
446				const newReceipt = await this.insertSplitReceipt(
447					ReceiptService.buildSplitReceiptInsert(original, splitAmount, splitDate, splitGroupId)
448				);
449				const updatedOriginal = await this.reduceOriginalAfterSplitOrRollback(
450					receiptId,
451					remainingAmount,
452					splitGroupId,
453					newReceipt.id
454				);
455	
456				return { newReceipt, updatedOriginal };
457			});
458		}
459	
460		/** #{#spl2b} Reject non-finite, non-positive, or sub-cent split amounts. */
461		private static validateSplitAmount(splitAmount: number): void {
462			if (!Number.isFinite(splitAmount) || splitAmount <= 0) {
463				throw new Error('Split amount must be a positive finite number');
464			}
465			// Check at most 2 decimal places
466			if (Math.round(splitAmount * 100) !== splitAmount * 100) {
467				throw new Error('Split amount can have at most 2 decimal places');
468			}
469		}
470	
471		/** #{#spl7c} Reject malformed or impossible (e.g. 2026-02-30) split dates when provided. */
472		private static validateSplitDate(splitDate?: string | null): void {
473			if (splitDate === undefined || splitDate === null) return;
474	
475			if (splitDate === '' || !/^\d{4}-\d{2}-\d{2}$/.test(splitDate)) {
476				throw new Error('Please enter a valid date');
477			}
478			const parsed = new Date(splitDate);
479			if (isNaN(parsed.getTime())) {
480				throw new Error('Please enter a valid date');
481			}
482			// Verify the date components match (catches 2026-02-30 etc.)
483			const [year, month, day] = splitDate.split('-').map(Number);
484			if (
485				parsed.getUTCFullYear() !== year ||
486				parsed.getUTCMonth() !== month - 1 ||
487				parsed.getUTCDate() !== day
488			) {
489				throw new Error('Please enter a valid date');
490			}
491		}
