493		private async fetchOriginalForSplit(receiptId: string): Promise<ReceiptRow> {
494			const { data: original, error: fetchError } = await supabase
495				.from('receipts')
496				.select('*')
497				.eq('id', receiptId)
498				.single();
499			if (fetchError) throw fetchError;
500			if (!original) throw new Error('Receipt not found');
501			return original as ReceiptRow;
502		}
503	
504		/** Validate the split against the original total and return what remains on the original. */
505		private static computeRemainingAmount(
506			originalAmount: number | null,
507			splitAmount: number
508		): number {
509			if (originalAmount == null || originalAmount <= 0) {
510				throw new Error('Cannot split a receipt with no amount');
511			}
512			const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
513			if (splitAmount >= originalAmount || remainingAmount <= 0) {
514				throw new Error('Split amount must be less than the receipt total');
515			}
516			return remainingAmount;
517		}
518	
519		/** The new split inherits the original's identity fields but never its transaction match. */
520		private static buildSplitReceiptInsert(
521			original: ReceiptRow,
522			splitAmount: number,
523			splitDate: string | null | undefined,
524			splitGroupId: string
525		): ReceiptInsert {
526			// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
527			const effectiveDate = splitDate ?? original.transaction_date;
528	
529			// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
530			const effectiveSuspicious = splitDate ? isSuspiciousDate(splitDate) : original.suspicious_date;
531	
532			return {
533				receipt_image_path: original.receipt_image_path,
534				transaction_date: effectiveDate,
535				total_amount: splitAmount,
536				tax: null,
537				merchant_name: original.merchant_name,
538				credit_card_name: original.credit_card_name,
539				credit_card_last_4: original.credit_card_last_4,
540				currency: original.currency,
541				matched_transaction_id: null,
542				suspicious_date: effectiveSuspicious,
543				split_group_id: splitGroupId
544			};
545		}
546	
547		private async insertSplitReceipt(newReceiptData: ReceiptInsert): Promise<ReceiptRow> {
548			const { data: newReceipt, error: insertError } = await supabase
549				.from('receipts')
550				.insert(newReceiptData)
551				.select('*')
552				.single();
553			if (insertError) throw insertError;
554			return newReceipt as ReceiptRow;
555		}
556	
557		/**
558		 * #{#spl5a} Update the original (reduce amount, set split_group_id, clear match).
559		 * On failure, best-effort delete of the just-inserted split keeps the pair consistent.
560		 */
561		private async reduceOriginalAfterSplitOrRollback(
562			receiptId: string,
563			remainingAmount: number,
564			splitGroupId: string,
565			newReceiptId: string
566		): Promise<ReceiptRow> {
567			const { data: updatedOriginal, error: updateError } = await supabase
568				.from('receipts')
569				.update({
570					total_amount: remainingAmount,
571					matched_transaction_id: null,
572					split_group_id: splitGroupId
573				})
574				.eq('id', receiptId)
575				.select('*')
576				.single();
577	
578			if (updateError) {
579				// Rollback: delete the newly created receipt
580				try {
581					await supabase.from('receipts').delete().eq('id', newReceiptId);
582				} catch {
583					// Best-effort rollback
584				}
585				throw updateError;
586			}
587	
588			return updatedOriginal as ReceiptRow;
589		}
590	
591		/**
592		 * #{#blk3a} Bulk delete multiple receipts in a single database operation
593		 * @param receiptIds Array of receipt IDs to delete
594		 * @returns Promise that resolves when deletion is complete
595		 */
596		async bulkDeleteReceipts(receiptIds: string[]): Promise<{ deletedCount: number }> {
597			return withRetry(async () => {
598				// Get authenticated user
599				const user = (await supabase.auth.getUser()).data.user;
600				if (!user) throw new Error('Not authenticated');
601	
602				// Delete all receipts in a single query using IN clause
603				// Only delete receipts belonging to the authenticated user
604				const { error } = await supabase
605					.from('receipts')
606					.delete()
607					.in('id', receiptIds)
608					.eq('user_id', user.id);
609	
610				if (error) throw error;
611	
612				// Return metadata about deletion
613				return { deletedCount: receiptIds.length };
614			});
615		}
616	}
