143		/**
144		 * Parse CSV/XLS/XLSX file and return parsed transactions - #{#xls2b}
145		 */
146		async parseCSV(
147			file: File,
148			creditCardType: CreditCardType
149		): Promise<{
150			transactions: ParsedTransaction[];
151			errors: string[];
152			detectedType?: CreditCardType;
153		}> {
154			return new Promise((resolve, reject) => {
155				const reader = new FileReader();
156	
157				reader.onload = (e) => {
158					try {
159						let csvContent: string;
160	
161						if (isExcelFile(file)) {
162							const buffer = e.target?.result as ArrayBuffer;
163							csvContent = convertExcelToCSV(buffer);
164						} else {
165							csvContent = e.target?.result as string;
166						}
167	
168						// Get the appropriate parser
169						const parser = CSVParserFactory.getParser(creditCardType);
170	
171						// Validate format
172						if (!parser.validateFormat(csvContent)) {
173							resolve({
174								transactions: [],
175								errors: [
176									`The file does not match the expected format for ${creditCardType}. Please verify you selected the correct credit card type.`
177								]
178							});
179							return;
180						}
181	
182						// Parse the CSV
183						const result = parser.parse(csvContent);
184						resolve({
185							transactions: result.transactions,
186							errors: result.errors
187						});
188					} catch (error: unknown) {
189						const message = error instanceof Error ? error.message : 'Unknown error';
190						reject(new Error(`Failed to parse file: ${message || 'Unknown error'}`));
191					}
192				};
193	
194				reader.onerror = () => {
195					reject(new Error('Failed to read file'));
196				};
197	
198				if (isExcelFile(file)) {
199					reader.readAsArrayBuffer(file);
200				} else {
201					reader.readAsText(file);
202				}
203			});
204		}
