267		/**
268		 * Import transactions from CSV/XLSX using count-based duplicate detection.
269		 *
270		 * Specifications: #{#tid1a} #{#tid2a} #{#tid2b} #{#tid5a}
271		 *
272		 * For each distinct `(transaction_date, vendor_name, amount)` key in the file,
273		 * inserts `max(0, fileCount - dbCount)` rows. Excluded (soft-deleted) rows count
274		 * toward `dbCount` so re-import does not resurrect them.
275		 */
276		async importFromCSV(
277			familyId: string,
278			file: File,
279			creditCardType: CreditCardType
280		): Promise<{
281			imported: number;
282			skipped: number;
283			errors: string[];
284		}> {
285			const parseResult = await this.parseCSV(file, creditCardType);
286	
287			if (parseResult.transactions.length === 0) {
288				return { imported: 0, skipped: 0, errors: parseResult.errors };
289			}
290	
291			const errors: string[] = [...parseResult.errors];
292	
293			// #{#tid2a}: single scoped query for existing rows in the file's date range.
294			// #{#tid2b}: scope to (family_id, credit_card_type).
295			// #{#tid5a}: no excluded filter — excluded rows count toward dbCount.
296			const dates = parseResult.transactions.map((t) => t.transaction_date);
297			const minDate = dates.reduce((a, b) => (a < b ? a : b));
298			const maxDate = dates.reduce((a, b) => (a > b ? a : b));
299	
300			const { data: existingRows, error: selectError } = await supabase
301				.from('transactions')
302				.select('transaction_date, vendor_name, amount')
303				.eq('family_id', familyId)
304				.eq('credit_card_type', creditCardType)
305				.gte('transaction_date', minDate)
306				.lte('transaction_date', maxDate);
307	
308			if (selectError) {
309				throw new Error(`Failed to load existing transactions: ${selectError.message}`);
310			}
311	
312			const plan = computeImportPlan(
313				parseResult.transactions,
314				(existingRows ?? []) as ExistingTransactionRow[]
315			);
316	
317			if (plan.toInsert.length === 0) {
318				return { imported: 0, skipped: plan.skipped, errors };
319			}
320	
321			const rowsToInsert = plan.toInsert.map((t) => ({
322				family_id: familyId,
323				transaction_date: t.transaction_date,
324				vendor_name: t.vendor_name,
325				amount: t.amount,
326				credit_card_type: creditCardType
327			}));
328	
329			const { error: insertError } = await supabase.from('transactions').insert(rowsToInsert);
330	
331			if (insertError) {
332				errors.push(`Failed to insert transactions: ${insertError.message}`);
333				return { imported: 0, skipped: plan.skipped, errors };
334			}
335	
336			return { imported: plan.toInsert.length, skipped: plan.skipped, errors };
337		}
