339		/**
340		 * Get transaction statistics for a family
341		 */
342		async getStats(familyId: string): Promise<{
343			totalTransactions: number;
344			totalAmount: number;
345			byCardType: Record<string, { count: number; total: number }>;
346		}> {
347			const transactions = await this.list(familyId, { includeExcluded: false });
348	
349			const stats = {
350				totalTransactions: transactions.length,
351				totalAmount: 0,
352				byCardType: {} as Record<string, { count: number; total: number }>
353			};
354	
355			for (const transaction of transactions) {
356				stats.totalAmount += transaction.amount;
357	
358				if (!stats.byCardType[transaction.credit_card_type]) {
359					stats.byCardType[transaction.credit_card_type] = { count: 0, total: 0 };
360				}
361	
362				stats.byCardType[transaction.credit_card_type].count++;
363				stats.byCardType[transaction.credit_card_type].total += transaction.amount;
364			}
365	
366			return stats;
367		}
