369		/**
370		 * Delete all transactions for a family (with optional filters) - #{#tbd1b}
371		 */
372		async deleteAll(
373			familyId: string,
374			options?: {
375				creditCardType?: CreditCardType;
376				beforeDate?: string;
377				afterDate?: string;
378			}
379		): Promise<number> {
380			// Count matching transactions before deleting
381			let countQuery = supabase
382				.from('transactions')
383				.select('id', { count: 'exact', head: true })
384				.eq('family_id', familyId);
385	
386			if (options?.creditCardType) {
387				countQuery = countQuery.eq('credit_card_type', options.creditCardType);
388			}
389			if (options?.afterDate) {
390				countQuery = countQuery.gte('transaction_date', options.afterDate);
391			}
392			if (options?.beforeDate) {
393				countQuery = countQuery.lt('transaction_date', options.beforeDate);
394			}
395	
396			const { count } = await countQuery;
397	
398			// Delete with the same filters
399			let deleteQuery = supabase.from('transactions').delete().eq('family_id', familyId);
400	
401			if (options?.creditCardType) {
402				deleteQuery = deleteQuery.eq('credit_card_type', options.creditCardType);
403			}
404			if (options?.afterDate) {
405				deleteQuery = deleteQuery.gte('transaction_date', options.afterDate);
406			}
407			if (options?.beforeDate) {
408				deleteQuery = deleteQuery.lt('transaction_date', options.beforeDate);
409			}
410	
411			const { error } = await deleteQuery;
412	
413			if (error) {
414				throw new Error(`Failed to delete transactions: ${error.message}`);
415			}
416	
417			return count || 0;
418		}
