65		/**
66		 * Performs automatic matching of receipts and transactions within a date range
67		 */
68		async reconcile(familyId: string, options: ReconciliationOptions): Promise<ReconciliationResult> {
69			return withRetry(async () => {
70				const tolerances = resolveMatchingTolerances(options);
71	
72				const allReceipts = await this.fetchReceiptsInRange(familyId, options);
73				const allTransactions = await this.fetchTransactionsInRange(familyId, options);
74	
75				const { alreadyMatchedReceipts, unmatchedReceipts, matchableTransactions } =
76					this.partitionForMatching(allReceipts, allTransactions, options.includeManuallMatched);
77	
78				const matchResult = this.performMatching(
79					unmatchedReceipts,
80					matchableTransactions,
81					tolerances
82				);
83	
84				const matchedPairs: MatchedPair[] = [
85					...matchResult.matched,
86					...this.buildManualMatchPairs(alreadyMatchedReceipts, allTransactions)
87				];
88	
89				// Excluded transactions are still shown in the UI, just never matched
90				const allUnmatchedTransactions: UnmatchedTransaction[] = [
91					...matchResult.unmatchedTransactions,
92					...this.buildExcludedUnmatchedTransactions(allTransactions)
93				];
94	
95				return {
96					matched: matchedPairs,
97					unmatchedReceipts: matchResult.unmatchedReceipts,
98					unmatchedTransactions: allUnmatchedTransactions,
99					stats: this.computeStats(allReceipts, allTransactions, matchedPairs, matchResult)
100				};
101			});
102		}
