137		/**
138		 * Splits the fetched rows into manual matches (kept as-is) and the pools
139		 * available to the automatic matching algorithm
140		 */
141		private partitionForMatching(
142			allReceipts: ReceiptRow[],
143			allTransactions: TransactionRow[],
144			includeManuallyMatched: boolean | undefined
145		): {
146			alreadyMatchedReceipts: ReceiptRow[];
147			unmatchedReceipts: ReceiptRow[];
148			matchableTransactions: TransactionRow[];
149		} {
150			const alreadyMatchedReceipts = includeManuallyMatched
151				? allReceipts.filter((r) => r.matched_transaction_id !== null)
152				: [];
153	
154			const unmatchedReceipts = allReceipts.filter((r) => r.matched_transaction_id === null);
155	
156			const alreadyMatchedTransactionIds = new Set(
157				alreadyMatchedReceipts
158					.map((r) => r.matched_transaction_id)
159					.filter((id): id is string => id !== null)
160			);
161	
162			// Excluded transactions are still shown in UI but not available for matching
163			const matchableTransactions = allTransactions.filter(
164				(t) => !alreadyMatchedTransactionIds.has(t.id) && !t.excluded
165			);
166	
167			return { alreadyMatchedReceipts, unmatchedReceipts, matchableTransactions };
168		}
