170		private buildManualMatchPairs(
171			alreadyMatchedReceipts: ReceiptRow[],
172			allTransactions: TransactionRow[]
173		): MatchedPair[] {
174			const pairs: MatchedPair[] = [];
175	
176			for (const receipt of alreadyMatchedReceipts) {
177				const transaction = allTransactions.find((t) => t.id === receipt.matched_transaction_id);
178				if (!transaction) continue;
179	
180				pairs.push({
181					receipt,
182					transaction,
183					matchConfidence: 'high' // Manual matches are high confidence
184				});
185			}
186	
187			return pairs;
188		}
