190		private buildExcludedUnmatchedTransactions(
191			allTransactions: TransactionRow[]
192		): UnmatchedTransaction[] {
193			return allTransactions
194				.filter((t) => t.excluded)
195				.map((transaction) => ({
196					transaction,
197					potentialMatches: [] // Excluded transactions don't get potential matches
198				}));
199		}
