201		private computeStats(
202			allReceipts: ReceiptRow[],
203			allTransactions: TransactionRow[],
204			matchedPairs: MatchedPair[],
205			matchResult: MatchingOutcome
206		): ReconciliationStats {
207			// Excluded transactions don't count toward totals
208			const nonExcludedTransactionCount = allTransactions.filter((t) => !t.excluded).length;
209	
210			return {
211				totalReceipts: allReceipts.length,
212				totalTransactions: nonExcludedTransactionCount,
213				matchedCount: matchedPairs.length,
214				unmatchedReceiptCount: matchResult.unmatchedReceipts.length,
215				unmatchedTransactionCount: matchResult.unmatchedTransactions.length,
216				matchRate:
217					allReceipts.length > 0 ? Math.round((matchedPairs.length / allReceipts.length) * 100) : 0
218			};
