221		/**
222		 * Core matching algorithm
223		 * Returns matched pairs and unmatched items
224		 */
225		private performMatching(
226			receipts: ReceiptRow[],
227			transactions: TransactionRow[],
228			tolerances: MatchingTolerances
229		): MatchingOutcome {
230			const matched = this.matchBestAvailablePairs(receipts, transactions, tolerances);
231	
232			const usedReceiptIds = new Set(matched.map((pair) => pair.receipt.id));
233			const usedTransactionIds = new Set(matched.map((pair) => pair.transaction.id));
234	
235			return {
236				matched,
237				unmatchedReceipts: this.buildUnmatchedReceipts(
238					receipts,
239					transactions,
240					usedReceiptIds,
241					usedTransactionIds,
242					tolerances
243				),
244				unmatchedTransactions: this.buildUnmatchedTransactions(
245					receipts,
246					transactions,
247					usedReceiptIds,
248					usedTransactionIds,
249					tolerances
250				)
251			};
252		}
253	
254		/**
255		 * Greedily pairs each receipt (in order) with its best still-available transaction
256		 */
257		private matchBestAvailablePairs(
258			receipts: ReceiptRow[],
259			transactions: TransactionRow[],
260			tolerances: MatchingTolerances
261		): MatchedPair[] {
262			const matched: MatchedPair[] = [];
263			const usedTransactionIds = new Set<string>();
264	
265			for (const receipt of receipts) {
266				const availableMatches = this.findPotentialMatches(receipt, transactions, tolerances).filter(
267					(pm) => !usedTransactionIds.has(pm.transaction.id)
268				);
269	
270				if (availableMatches.length === 0) continue;
271	
272				// Take the best match (first one, as they're sorted by confidence)
273				const bestMatch = availableMatches[0];
274				matched.push({
275					receipt,
276					transaction: bestMatch.transaction,
277					matchConfidence: bestMatch.confidence
278				});
279				usedTransactionIds.add(bestMatch.transaction.id);
280			}
281	
282			return matched;
283		}
284	
285		private buildUnmatchedReceipts(
286			receipts: ReceiptRow[],
287			transactions: TransactionRow[],
288			usedReceiptIds: Set<string>,
289			usedTransactionIds: Set<string>,
290			tolerances: MatchingTolerances
291		): UnmatchedReceipt[] {
292			return receipts
293				.filter((r) => !usedReceiptIds.has(r.id))
294				.map((receipt) => ({
295					receipt,
296					potentialMatches: this.findPotentialMatches(receipt, transactions, tolerances)
297						.filter((pm) => !usedTransactionIds.has(pm.transaction.id))
298						.map((pm) => pm.transaction)
299				}));
300		}
301	
302		private buildUnmatchedTransactions(
303			receipts: ReceiptRow[],
304			transactions: TransactionRow[],
305			usedReceiptIds: Set<string>,
306			usedTransactionIds: Set<string>,
307			tolerances: MatchingTolerances
308		): UnmatchedTransaction[] {
309			return transactions
310				.filter((t) => !usedTransactionIds.has(t.id))
311				.map((transaction) => ({
312					transaction,
313					potentialMatches: this.findPotentialMatchesForTransaction(transaction, receipts, tolerances)
314						.filter((pm) => !usedReceiptIds.has(pm.receipt.id))
315						.map((pm) => pm.receipt)
316				}));
317		}
