319		/**
320		 * Finds potential transaction matches for a given receipt, best first
321		 */
322		private findPotentialMatches(
323			receipt: ReceiptRow,
324			transactions: TransactionRow[],
325			tolerances: MatchingTolerances
326		): Array<{ transaction: TransactionRow; confidence: MatchConfidence }> {
327			const scored: Array<{ transaction: TransactionRow } & ScoredCandidate> = [];
328	
329			for (const transaction of transactions) {
330				const candidate = this.scoreCandidate(receipt, transaction, tolerances);
331				if (candidate) scored.push({ transaction, ...candidate });
332			}
333	
334			scored.sort((a, b) => b.score - a.score);
335			return scored.map(({ transaction, confidence }) => ({ transaction, confidence }));
336		}
337	
338		/**
339		 * Finds potential receipt matches for a given transaction, best first
340		 */
341		private findPotentialMatchesForTransaction(
342			transaction: TransactionRow,
343			receipts: ReceiptRow[],
344			tolerances: MatchingTolerances
345		): Array<{ receipt: ReceiptRow; confidence: MatchConfidence }> {
346			const scored: Array<{ receipt: ReceiptRow } & ScoredCandidate> = [];
347	
348			for (const receipt of receipts) {
349				const candidate = this.scoreCandidate(receipt, transaction, tolerances);
350				if (candidate) scored.push({ receipt, ...candidate });
351			}
352	
353			scored.sort((a, b) => b.score - a.score);
354			return scored.map(({ receipt, confidence }) => ({ receipt, confidence }));
355		}
356	
357		/**
358		 * Shared matching predicate: scores a receipt/transaction pair, or returns
359		 * null when the pair is outside the amount/date tolerances (no match)
360		 */
361		private scoreCandidate(
362			receipt: ReceiptRow,
363			transaction: TransactionRow,
364			tolerances: MatchingTolerances
365		): ScoredCandidate | null {
366			if (!receipt.total_amount || !receipt.transaction_date) return null;
367	
368			// #{#fcr3a} Foreign currency receipts are converted to CAD using the rate
369			// stored on the receipt, and compared with a percentage tolerance
370			const isForeignCurrency = receipt.currency !== null && receipt.currency !== 'CAD';
371			if (isForeignCurrency && !receipt.exchange_rate_to_cad) {
372				return null; // No exchange rate stored — cannot match this receipt
373			}
374	
375			const rawReceiptAmount = Math.abs(receipt.total_amount);
376			const receiptAmountCAD =
377				isForeignCurrency && receipt.exchange_rate_to_cad
378					? rawReceiptAmount * receipt.exchange_rate_to_cad
379					: rawReceiptAmount;
380	
381			const transactionAmount = Math.abs(transaction.amount);
382			const amountDiff = Math.abs(receiptAmountCAD - transactionAmount);
383			const percentDiff = transactionAmount > 0 ? amountDiff / transactionAmount : 1;
384	
385			const withinAmountTolerance = isForeignCurrency
386				? percentDiff <= tolerances.foreignCurrencyTolerancePercent
387				: amountDiff <= tolerances.amountTolerance;
388			if (!withinAmountTolerance) return null;
389	
390			const daysDiff = Math.abs(
391				(new Date(receipt.transaction_date).getTime() -
392					new Date(transaction.transaction_date).getTime()) /
393					MS_PER_DAY
394			);
395			if (daysDiff > tolerances.maxDaysDifference) return null;
396	
397			return isForeignCurrency
398				? this.scoreForeignCurrencyCandidate(percentDiff, daysDiff)
399				: this.scoreCadCandidate(amountDiff, daysDiff);
400		}
401	
402		/**
403		 * #{#fcr3a} Foreign currency confidence based on percentage difference
404		 */
405		private scoreForeignCurrencyCandidate(percentDiff: number, daysDiff: number): ScoredCandidate {
406			let score: number;
407			if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) score = SCORE_AMOUNT_EXACT;
408			else if (percentDiff <= FC_MEDIUM_CONFIDENCE_PERCENT) score = SCORE_AMOUNT_CLOSE;
409			else score = SCORE_AMOUNT_NEAR;
410	
411			let confidence: MatchConfidence = 'low';
412			if (daysDiff === 0) {
413				score += SCORE_SAME_DAY;
414				if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) confidence = 'high';
415				else if (percentDiff <= FC_MEDIUM_CONFIDENCE_PERCENT) confidence = 'medium';
416			} else if (daysDiff <= 1) {
417				score += SCORE_ONE_DAY_APART;
418				if (percentDiff <= FC_HIGH_CONFIDENCE_PERCENT) confidence = 'medium';
419			} else {
420				score += SCORE_WITHIN_RANGE;
421			}
422	
423			return { score, confidence };
424		}
425	
426		/**
427		 * CAD confidence based on date proximity, with a bonus for exact amounts
428		 */
429		private scoreCadCandidate(amountDiff: number, daysDiff: number): ScoredCandidate {
430			let score = amountDiff < EXACT_AMOUNT_DIFF ? SCORE_AMOUNT_EXACT : 0;
431	
432			let confidence: MatchConfidence;
433			if (daysDiff === 0) {
434				score += SCORE_SAME_DAY;
435				confidence = 'high';
436			} else if (daysDiff <= 1) {
437				score += SCORE_ONE_DAY_APART;
438				confidence = 'medium';
439			} else {
440				score += SCORE_WITHIN_RANGE;
441				confidence = 'low';
442			}
443	
444			return { score, confidence };
445		}
