448		 * Manually match a receipt to a transaction
449		 */
450		async manualMatch(request: ManualMatchRequest): Promise<ReceiptRow> {
451			return withRetry(async () => {
452				const { data, error } = await supabase
453					.from('receipts')
454					.update({ matched_transaction_id: request.transactionId })
455					.eq('id', request.receiptId)
456					.select('*')
457					.single();
458	
459				if (error) throw error;
460				return data as ReceiptRow;
461			});
462		}
