481		/**
482		 * Converts reconciliation result to display rows for the UI table
483		 */
484		convertToDisplayRows(
485			result: ReconciliationResult,
486			sort?: ReconciliationSort
487		): ReconciliationDisplayRow[] {
488			const rows: ReconciliationDisplayRow[] = [];
489	
490			// #{#fcr5b} Helper to compute converted CAD amount from receipt's stored rate
491			const getConvertedCAD = (receipt: ReceiptRow | null): number | null => {
492				if (!receipt || !receipt.total_amount) return null;
493				if (!receipt.currency || receipt.currency === 'CAD') return null;
494				if (!receipt.exchange_rate_to_cad) return null;
495				return receipt.total_amount * receipt.exchange_rate_to_cad;
496			};
497	
498			// Add matched pairs (green rows at top)
499			for (const pair of result.matched) {
500				rows.push({
501					id: `matched-${pair.receipt.id}-${pair.transaction.id}`,
502					type: 'matched',
503					receipt: pair.receipt,
504					transaction: pair.transaction,
505					date: pair.receipt.transaction_date,
506					vendor: pair.receipt.merchant_name || pair.transaction.vendor_name,
507					amount: pair.receipt.total_amount,
508					creditCard: pair.transaction.credit_card_type,
509					matchConfidence: pair.matchConfidence,
510					convertedAmountCAD: getConvertedCAD(pair.receipt)
511				});
512			}
513	
514			// Add unmatched receipts
515			for (const unmatched of result.unmatchedReceipts) {
516				rows.push({
517					id: `receipt-${unmatched.receipt.id}`,
518					type: 'unmatchedReceipt',
519					receipt: unmatched.receipt,
520					transaction: null,
521					date: unmatched.receipt.transaction_date,
522					vendor: unmatched.receipt.merchant_name,
523					amount: unmatched.receipt.total_amount,
524					creditCard: unmatched.receipt.credit_card_name,
525					convertedAmountCAD: getConvertedCAD(unmatched.receipt)
526				});
527			}
528	
529			// Add unmatched transactions
530			for (const unmatched of result.unmatchedTransactions) {
531				rows.push({
532					id: `transaction-${unmatched.transaction.id}`,
533					type: 'unmatchedTransaction',
534					receipt: null,
535					transaction: unmatched.transaction,
536					date: unmatched.transaction.transaction_date,
537					vendor: unmatched.transaction.vendor_name,
538					amount: unmatched.transaction.amount,
539					creditCard: unmatched.transaction.credit_card_type,
540					convertedAmountCAD: null
541				});
542			}
543	
544			// Apply sorting if specified
545			if (sort) {
546				return this.sortDisplayRows(rows, sort);
547			}
548	
549			return rows;
550		}
551	
552		/**
553		 * Sorts display rows by the specified field and direction
554		 */
555		private sortDisplayRows(
556			rows: ReconciliationDisplayRow[],
557			sort: ReconciliationSort
558		): ReconciliationDisplayRow[] {
559			const sortedRows = [...rows];
560			const direction = sort.direction === 'asc' ? 1 : -1;
561	
562			sortedRows.sort((a, b) => {
563				let aVal: string | number;
564				let bVal: string | number;
565	
566				switch (sort.field) {
567					case 'date':
568						aVal = a.date || '';
569						bVal = b.date || '';
570						break;
571					case 'vendor':
572						aVal = a.vendor || '';
573						bVal = b.vendor || '';
574						break;
575					case 'amount':
576						aVal = a.amount || 0;
577						bVal = b.amount || 0;
578						break;
579					case 'creditCard':
580						aVal = a.creditCard || '';
581						bVal = b.creditCard || '';
582						break;
583					case 'matchStatus': {
584						const statusOrder = { matched: 0, unmatchedReceipt: 1, unmatchedTransaction: 2 };
585						aVal = statusOrder[a.type];
586						bVal = statusOrder[b.type];
587						break;
588					}
589					default:
590						return 0;
591				}
592	
593				if (typeof aVal === 'string') {
594					return direction * aVal.localeCompare(bVal as string);
595				} else {
596					return direction * (aVal - (bVal as number));
597				}
598			});
599	
600			return sortedRows;
601		}
602	}
