144		async function deleteTransaction(t: TransactionRow): Promise<void> {
145			if (!confirm('Delete this transaction?')) return;
146			deleting.add(t.id);
147			deleting = new Set(deleting);
148			error = null;
149			try {
150				await TransactionService.get().delete(t.id);
151				allTransactions = allTransactions.filter((x) => x.id !== t.id);
152				successMessage = 'Transaction deleted';
153			} catch (e: any) {
154				error = e?.message ?? 'Failed to delete transaction';
155			} finally {
156				deleting.delete(t.id);
157				deleting = new Set(deleting);
158			}
159		}
