162		async function deleteSelected(): Promise<void> {
163			const ids = Array.from(transactionSelection.selected);
164			if (ids.length === 0) return;
165			if (!confirm(`Delete ${ids.length} selected transaction${ids.length === 1 ? '' : 's'}?`)) {
166				return;
167			}
168	
169			bulkDeleting = true;
170			error = null;
171			const original = [...allTransactions];
172			// Optimistic update — remove from UI immediately
173			allTransactions = allTransactions.filter((t) => !transactionSelection.selected.has(t.id));
