175			try {
176				await TransactionService.get().deleteByIds(ids);
177				successMessage = `${ids.length} transaction${ids.length === 1 ? '' : 's'} deleted`;
178				transactionSelection = emptySelection();
179			} catch (e: any) {
180				// Rollback on failure
181				allTransactions = original;
182				error = e?.message ?? 'Failed to delete transactions';
183			} finally {
184				bulkDeleting = false;
185			}
186		}
