227		function applyClientFilters(txns: TransactionRow[]): TransactionRow[] {
228			return txns.filter((t) => {
229				// #{#sdf1b} Filter by date range using URL parameters
230				if (!matchesDateRange(t.transaction_date, urlDateFrom, urlDateTo)) return false;
231	
232				// Filter by vendor name (local state)
233				if (filterVendor) {
234					const vendorSearch = filterVendor.toLowerCase();
235					const vendor = t.vendor_name.toLowerCase();
236					if (!vendor.includes(vendorSearch)) return false;
237				}
238	
239				// Filter by amount range (local state)
240				if (filterAmountMin) {
241					const minAmount = parseFloat(filterAmountMin);
242					if (!isNaN(minAmount) && Math.abs(t.amount) < minAmount) return false;
243				}
244				if (filterAmountMax) {
245					const maxAmount = parseFloat(filterAmountMax);
246					if (!isNaN(maxAmount) && Math.abs(t.amount) > maxAmount) return false;
247				}
248	
249				// #{#tcf1a} Filter by credit/bank type (local state)
250				if (filterCreditCardType !== 'all') {
251					if (t.credit_card_type !== filterCreditCardType) return false;
252				}
253	
254				return true;
255			});
256		}
