545			const index = groupReceipts.findIndex((r) => r.id === receipt.id);
546	
547			return {
548				index: index + 1,
549				total: groupReceipts.length,
550				groupAmounts: groupReceipts.map((r) => r.total_amount ?? 0)
551			};
