561			);
562			if (row && row.transaction) {
563				manualReceiptForm.merchant_name = row.transaction.vendor_name;
564				manualReceiptForm.total_amount = Math.abs(row.transaction.amount).toFixed(2);
565				manualReceiptForm.transaction_date = row.transaction.transaction_date;
