575		async function createManualReceipt() {
576			if (!selectedUnmatchedTransaction) return;
577	
578			error = null;
579			try {
580				const amount = parseFloat(manualReceiptForm.total_amount);
581				if (isNaN(amount)) {
582					error = 'Invalid amount';
583					return;
584				}
585	
586				// Create the manual receipt
587				const receipt = await ReceiptService.get().createManual({
