590					transaction_date: manualReceiptForm.transaction_date
591				});
592	
593				// Match it to the transaction
594				await ReconciliationService.get().manualMatch({
595					receiptId: receipt.id,
596					transactionId: selectedUnmatchedTransaction
597				});
