166		async function loadSignedUrls(paths: string[]) {
167			const cached = signedUrls;
168			const newUrls: Record<string, string> = {};
169			const missing: string[] = [];
170			for (const path of paths) {
171				if (cached[path]) newUrls[path] = cached[path];
172				else missing.push(path);
173			}
174			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
175			if (missing.length > 0) {
176				Object.assign(newUrls, await getSignedReceiptUrls(missing));
177			}
178			signedUrls = newUrls;
179		}
