317		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
318			// #{#dup5a} Pre-compute duplicate IDs when filter is active
319			let dupeIds: Set<string> | null = null;
320			if (filterDuplicates) {
321				const dupes = detectDuplicates(rcts);
322				// eslint-disable-next-line svelte/prefer-svelte-reactivity -- local, non-reactive lookup set built and read within this call; SvelteSet would be inappropriate here
323				dupeIds = new Set<string>();
324				for (const ids of dupes.values()) {
325					for (const id of ids) dupeIds.add(id);
326				}
327			}
328	
329			return rcts.filter((r) => {
330				// #{#dtv3a} Filter by suspicious_date (Needs Review)
331				if (filterNeedsReview && !r.suspicious_date) return false;
332	
333				// #{#dup5a} Filter by duplicate status
334				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
335	
336				// #{#sdf1b} Filter by date range using URL parameters
337				if (!matchesDateRange(r.transaction_date, urlDateFrom, urlDateTo)) return false;
338	
339				// Filter by merchant name (local state)
340				if (filterMerchant) {
341					const merchantSearch = filterMerchant.toLowerCase();
342					const merchant = (r.merchant_name || '').toLowerCase();
343					if (!merchant.includes(merchantSearch)) return false;
344				}
345	
346				// Filter by amount range (local state)
347				if (filterAmountMin && r.total_amount !== null) {
348					const minAmount = parseFloat(filterAmountMin);
349					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
350				}
351				if (filterAmountMax && r.total_amount !== null) {
352					const maxAmount = parseFloat(filterAmountMax);
353					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
354				}
355	
356				return true;
357			});
358		}
