574		/**
575		 * #{#exp1a} #{#exp4b} Handle CSV export
576		 * #{#exp1b} Respects current filter (exports filteredExpenses)
577		 * #{#exp3b} Shows loading state and feedback
578		 * #{#edf2a} CSV export respects date filters and includes date range in filename
579		 */
580		async function handleExportCSV() {
581			// #{#exp1a} Criterion 3: Disabled when no expenses
582			if (filteredExpenses.length === 0) {
583				return;
584			}
585	
586			isExporting = true;
587			try {
588				// #{#exp4b} Criterion 2: Export filtered expenses
589				const csvContent = csvService.exportExpensesToCSV(filteredExpenses);
590	
591				// #{#edf2a} Criterion 2: Generate filename based on current filters
592				// Date filter takes precedence in filename
593				let filename: string;
594	
595				if (urlDateFrom && urlDateTo) {
596					filename = `expenses_${urlDateFrom}_to_${urlDateTo}.csv`;
597				} else if (urlDateFrom) {
598					filename = `expenses_from_${urlDateFrom}.csv`;
599				} else if (urlDateTo) {
600					filename = `expenses_to_${urlDateTo}.csv`;
601				} else if (showUncategorizedOnly) {
602					filename = 'expenses_uncategorized.csv';
603				} else if (selectedCategoryIds.length === 1) {
604					const category = categories.find((c) => c.id === selectedCategoryIds[0]);
605					const catName = category?.name.toLowerCase().replace(/\s+/g, '_') || 'filtered';
606					filename = `expenses_${catName}.csv`;
607				} else if (selectedCategoryIds.length > 1) {
608					filename = 'expenses_multiple_categories.csv';
609				} else {
610					filename = csvService.generateFilename('all');
611				}
612	
613				// #{#exp3a} Criterion 1: Download CSV
614				csvService.downloadCSV(csvContent, filename);
615	
616				// #{#exp3b} Criterion 3: Success feedback
617				showToast(
618					`CSV exported successfully: ${filteredExpenses.length} expense${filteredExpenses.length !== 1 ? 's' : ''}`,
619					'success'
620				);
621			} catch (err) {
622				// #{#exp3b} Criterion 4: Error feedback
623				console.error('Error exporting CSV:', err);
624				showToast(
625					`Failed to export CSV: ${err instanceof Error ? err.message : 'Unknown error'}`,
626					'error'
627				);
628			} finally {
629				isExporting = false;
630			}
631		}
