633		/**
634		 * #{#cre1a} #{#cre4b} Handle PDF receipt export
635		 * #{#cre1b} Respects current filters (exports filteredExpenses)
636		 * #{#cre4a} Shows progress and supports cancellation
637		 */
638		async function handleExportPDF() {
639			if (
640				!PDFExportService.shouldEnablePDFExport({
641					filteredExpensesCount: filteredExpenses.length,
642					selectedCategoryIds,
643					showUncategorizedOnly,
644					isExporting: isExportingPDF
645				})
646			) {
647				return;
648			}
649	
650			isExportingPDF = true;
651			pdfExportProgress = 'Preparing receipt data...';
652			pdfAbortController = new AbortController();
653	
654			try {
655				// #{#cre1b} Build category names for the selected filters
656				const selectedCategories = categories.filter((c) => selectedCategoryIds.includes(c.id));
657				const categoryNames = selectedCategories.map((c) => c.name);
658	
659				// #{#cre3a} Fetch receipt images via signed URLs
660				const fetchImageFn = async (path: string): Promise<Uint8Array | null> => {
661					const signedUrl = await getSignedReceiptUrl(path, 300); // 5 min expiry
662					if (!signedUrl) return null;
663					const response = await fetch(signedUrl);
664					if (!response.ok) return null;
665					const buffer = await response.arrayBuffer();
666					return new Uint8Array(buffer);
667				};
668	
669				// #{#cre1b} Build date range from URL filters
670				const dateRange =
671					urlDateFrom && urlDateTo
672						? { start: urlDateFrom, end: urlDateTo }
673						: urlDateFrom
674							? { start: urlDateFrom, end: urlDateFrom }
675							: null;
676	
677				const pdfBytes = await pdfService.generateReceiptPDF(filteredExpenses, {
678					categories: selectedCategories,
679					dateRange,
680					fetchImageFn,
681					abortSignal: pdfAbortController.signal,
682					onProgress: (step: string) => {
683						pdfExportProgress = step;
684					}
685				});
686	
687				// #{#cre3b} Generate filename and download
688				const filename = pdfService.generateFilename(categoryNames, dateRange);
689				pdfService.downloadPDF(pdfBytes, filename);
690	
691				// #{#cre4a} Success feedback
692				const totalAmount = pdfService.calculateSubtotal(filteredExpenses);
693				showToast(
694					`PDF exported: ${filteredExpenses.length} receipt${filteredExpenses.length !== 1 ? 's' : ''} across ${categoryNames.length} categor${categoryNames.length !== 1 ? 'ies' : 'y'}, ${pdfService.formatAmount(totalAmount)} total`,
695					'success'
696				);
697			} catch (err) {
698				if (err instanceof Error && /abort|cancel/i.test(err.message)) {
699					showToast('PDF export cancelled', 'success');
700				} else {
701					console.error('Error exporting PDF:', err);
702					showToast(
703						`Failed to generate PDF: ${err instanceof Error ? err.message : 'Unknown error'}`,
704						'error'
705					);
706				}
707			} finally {
708				isExportingPDF = false;
709				pdfExportProgress = '';
710				pdfAbortController = null;
711			}
712		}
