714		/**
715		 * Show toast notification
716		 * #{#exp3b} Criterion 3, 4: Success/error feedback
717		 */
718		function showToast(message: string, type: 'success' | 'error') {
719			successMessage = message;
720			setTimeout(
721				() => {
722					successMessage = null;
723				},
724				type === 'success' ? 3000 : 5000
725			);
726		}
