728		// #{#sec1a} Signed URL cache for receipt images
729		let signedUrls: Record<string, string> = $state({});
730	
731		// #{#sec1a} Load signed URLs whenever expenses change
732		// Uses untrack to read signedUrls without creating a reactive loop
733		$effect(() => {
734			const paths = expenses.map((e) => e.receipt_image_path).filter((p): p is string => !!p);
735			untrack(() => loadSignedUrls(paths));
736		});
737	
738		async function loadSignedUrls(paths: string[]) {
739			const cached = signedUrls;
740			const newUrls: Record<string, string> = {};
741			const missing: string[] = [];
742			for (const path of paths) {
743				if (cached[path]) newUrls[path] = cached[path];
744				else missing.push(path);
745			}
746			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
747			if (missing.length > 0) {
748				Object.assign(newUrls, await getSignedReceiptUrls(missing));
749			}
750			signedUrls = newUrls;
751		}
752	
753		function getImageUrl(path: string | null): string | null {
754			if (!path) return null;
755			return signedUrls[path] ?? null;
756		}
