	(supabase.auth.getUser as any).mockResolvedValue({
		data: { user: null }
	});

	const receiptIds = ['id-1', 'id-2'];

	// Should throw error if no user
	// Note: This depends on implementation checking for auth
	try {
		await service.bulkDeleteReceipts(receiptIds);
		// If no auth check, test will show we need to add it
	} catch (error: any) {
		expect(error.message).toMatch(/auth|user/i);
	}
});

